   312→func (s *Service) areSidecarsAvailable(ctx context.Context, avs das.AvailabilityStore, roBlock consensusblocks.ROBlock) error {
   313→	blockVersion := roBlock.Version()
   314→	block := roBlock.Block()
   315→	slot := block.Slot()
   316→
   317→	if blockVersion >= version.Fulu {
   318→		if err := s.areDataColumnsAvailable(ctx, roBlock.Root(), block); err != nil {
   319→			return errors.Wrapf(err, "are data columns available for block %#x with slot %d", roBlock.Root(), slot)
   320→		}
   321→
   322→		return nil
   323→	}
   324→
   325→	if blockVersion >= version.Deneb {
   326→		if err := avs.IsDataAvailable(ctx, s.CurrentSlot(), roBlock); err != nil {
   327→			return errors.Wrapf(err, "could not validate sidecar availability at slot %d", slot)
   328→		}
   329→
   330→		return nil
   331→	}
   332→
   333→	return nil
   334→}
