   377→// Epoch boundary tasks: it copies the headState and updates the epoch boundary
   378→// caches.
   379→func (s *Service) handleEpochBoundary(ctx context.Context, slot primitives.Slot, headState state.BeaconState, blockRoot []byte) error {
   380→	ctx, span := trace.StartSpan(ctx, "blockChain.handleEpochBoundary")
   381→	defer span.End()
   382→	// return early if we are advancing to a past epoch
   383→	if slot < headState.Slot() {
   384→		return nil
   385→	}
   386→	if !slots.IsEpochEnd(slot) {
   387→		return nil
   388→	}
   389→	copied := headState.Copy()
   390→	copied, err := transition.ProcessSlotsUsingNextSlotCache(ctx, copied, blockRoot, slot+1)
   391→	if err != nil {
   392→		return err
   393→	}
   394→	return s.updateEpochBoundaryCaches(ctx, copied)
   395→}
