   436→// This saves post state info to DB or cache. This also saves post state info to fork choice store.
   437→// Post state info consists of processed block and state. Do not call this method unless the block and state are verified.
   438→func (s *Service) savePostStateInfo(ctx context.Context, r [32]byte, b interfaces.ReadOnlySignedBeaconBlock, st state.BeaconState) error {
   439→	ctx, span := trace.StartSpan(ctx, "blockChain.savePostStateInfo")
