   548→// validateMergeTransitionBlock validates the merge transition block.
   549→func (s *Service) validateMergeTransitionBlock(ctx context.Context, stateVersion int, stateHeader interfaces.ExecutionData, blk interfaces.ReadOnlySignedBeaconBlock) error {
   550→	// Skip validation if block is older than Bellatrix.
   551→	if blocks.IsPreBellatrixVersion(blk.Block().Version()) {
   552→		return nil
   553→	}
   554→
   555→	// Skip validation if block has an empty payload.
   556→	payload, err := blk.Block().Body().Execution()
   557→	if err != nil {
   558→		return invalidBlock{error: err}
   559→	}
   560→	isEmpty, err := consensusblocks.IsEmptyExecutionData(payload)
   561→	if err != nil {
   562→		return err
   563→	}
   564→	if isEmpty {
   565→		return nil
   566→	}
   567→
   568→	// Handle case where pre-state is Altair but block contains payload.
   569→	// To reach here, the block must have contained a valid payload.
   570→	if blocks.IsPreBellatrixVersion(stateVersion) {
   571→		return s.validateMergeBlock(ctx, blk)
   572→	}
   573→
   574→	// Skip validation if the block is not a merge transition block.
   575→	// To reach here. The payload must be non-empty. If the state header is empty then it's at transition.
   576→	empty, err := consensusblocks.IsEmptyExecutionData(stateHeader)
   577→	if err != nil {
   578→		return err
   579→	}
   580→	if !empty {
   581→		return nil
   582→	}
   583→	return s.validateMergeBlock(ctx, blk)
   584→}
