   586→// This routine checks if there is a cached proposer payload ID available for the next slot proposer.
   587→// If there is not, it will call forkchoice updated with the correct payload attribute then cache the payload ID.
   588→func (s *Service) runLateBlockTasks() {
   589→	if err := s.waitForSync(); err != nil {
   590→		log.WithError(err).Error("Failed to wait for initial sync")
   591→		return
   592→	}
   593→
   594→	attThreshold := params.BeaconConfig().SecondsPerSlot / 3
   595→	ticker := slots.NewSlotTickerWithOffset(s.genesisTime, time.Duration(attThreshold)*time.Second, params.BeaconConfig().SecondsPerSlot)
   596→	for {
   597→		select {
   598→		case <-ticker.C():
   599→			s.lateBlockTasks(s.ctx)
   600→		case <-s.ctx.Done():
   601→			log.Debug("Context closed, exiting routine")
   602→			return
   603→		}
   604→	}
   605→}
   606→
   607→// missingBlobIndices uses the expected commitments from the block to determine
   608→// which BlobSidecar indices would need to be in the database for DA success.
   609→// It returns a map where each key represents a missing BlobSidecar index.
   610→// An empty map means we have all indices; a non-empty map can be used to compare incoming
   611→// BlobSidecars against the set of known missing sidecars.
   612→func missingBlobIndices(store *filesystem.BlobStorage, root [fieldparams.RootLength]byte, expected [][]byte, slot primitives.Slot) (map[uint64]bool, error) {
   613→	maxBlobsPerBlock := params.BeaconConfig().MaxBlobsPerBlock(slot)
   614→	if len(expected) == 0 {
   615→		return nil, nil
   616→	}
   617→	if len(expected) > maxBlobsPerBlock {
   618→		return nil, errMaxBlobsExceeded
   619→	}
   620→	indices := store.Summary(root)
   621→	missing := make(map[uint64]bool, len(expected))
   622→	for i := range expected {
   623→		if len(expected[i]) > 0 && !indices.HasIndex(uint64(i)) {
   624→			missing[uint64(i)] = true
   625→		}
   626→	}
   627→	return missing, nil
   628→}
   629→
   630→// missingDataColumnIndices uses the expected data columns from the block to determine
   631→// which DataColumnSidecar indices would need to be in the database for DA success.
   632→// It returns a map where each key represents a missing DataColumnSidecar index.
   633→// An empty map means we have all indices; a non-empty map can be used to compare incoming
   634→// DataColumns against the set of known missing sidecars.
   635→func missingDataColumnIndices(store *filesystem.DataColumnStorage, root [fieldparams.RootLength]byte, expected map[uint64]bool) (map[uint64]bool, error) {
   636→	if len(expected) == 0 {
   637→		return nil, nil
   638→	}
   639→
   640→	numberOfColumns := params.BeaconConfig().NumberOfColumns
   641→
   642→	if uint64(len(expected)) > numberOfColumns {
   643→		return nil, errMaxDataColumnsExceeded
   644→	}
   645→
   646→	// Get a summary of the data columns stored in the database.
   647→	summary := store.Summary(root)
   648→
   649→	// Check all expected data columns against the summary.
   650→	missing := make(map[uint64]bool)
   651→	for column := range expected {
   652→		if !summary.HasIndex(column) {
   653→			missing[column] = true
   654→		}
   655→	}
   656→
   657→	return missing, nil
   658→}
   659→
   660→// isDataAvailable blocks until all sidecars committed to in the block are available,
   661→// or an error or context cancellation occurs. A nil result means that the data availability check is successful.
   662→// The function will first check the database to see if all sidecars have been persisted. If any
   663→// sidecars are missing, it will then read from the sidecar notifier channel for the given root until the channel is
   664→// closed, the context hits cancellation/timeout, or notifications have been received for all the missing sidecars.
   665→func (s *Service) isDataAvailable(
   666→	ctx context.Context,
   667→	root [fieldparams.RootLength]byte,
   668→	signedBlock interfaces.ReadOnlySignedBeaconBlock,
   669→) error {
   670→	block := signedBlock.Block()
   671→	if block == nil {
   672→		return errors.New("invalid nil beacon block")
   673→	}
   674→
   675→	blockVersion := block.Version()
   676→	if blockVersion >= version.Fulu {
   677→		return s.areDataColumnsAvailable(ctx, root, block)
   678→	}
   679→
   680→	if blockVersion >= version.Deneb {
   681→		return s.areBlobsAvailable(ctx, root, block)
   682→	}
   683→
   684→	return nil
   685→}
   686→
   687→// areDataColumnsAvailable blocks until all data columns committed to in the block are available,
   688→// or an error or context cancellation occurs. A nil result means that the data availability check is successful.
   689→func (s *Service) areDataColumnsAvailable(
   690→	ctx context.Context,
   691→	root [fieldparams.RootLength]byte,
   692→	block interfaces.ReadOnlyBeaconBlock,
   693→) error {
   694→	samplesPerSlot := params.BeaconConfig().SamplesPerSlot
   695→
   696→	// We are only required to check within MIN_EPOCHS_FOR_DATA_COLUMN_SIDECARS_REQUESTS
   697→	blockSlot, currentSlot := block.Slot(), s.CurrentSlot()
   698→	blockEpoch, currentEpoch := slots.ToEpoch(blockSlot), slots.ToEpoch(currentSlot)
   699→	if !params.WithinDAPeriod(blockEpoch, currentEpoch) {
   700→		return nil
   701→	}
   702→
   703→	body := block.Body()
   704→	if body == nil {
   705→		return errors.New("invalid nil beacon block body")
   706→	}
   707→
   708→	kzgCommitments, err := body.BlobKzgCommitments()
   709→	if err != nil {
   710→		return errors.Wrap(err, "blob KZG commitments")
   711→	}
   712→
   713→	// If block has not commitments there is nothing to wait for.
   714→	if len(kzgCommitments) == 0 {
   715→		return nil
   716→	}
   717→
   718→	// All columns to sample need to be available for the block to be considered available.
   719→	nodeID := s.cfg.P2P.NodeID()
   720→
   721→	// Get the custody group sampling size for the node.
   722→	custodyGroupCount, err := s.cfg.P2P.CustodyGroupCount()
   723→	if err != nil {
   724→		return errors.Wrap(err, "custody group count")
   725→	}
   726→
   727→	// Compute the sampling size.
   728→	// https://github.com/ethereum/consensus-specs/blob/master/specs/fulu/das-core.md#custody-sampling
   729→	samplingSize := max(samplesPerSlot, custodyGroupCount)
   730→
   731→	// Get the peer info for the node.
   732→	peerInfo, _, err := peerdas.Info(nodeID, samplingSize)
   733→	if err != nil {
   734→		return errors.Wrap(err, "peer info")
   735→	}
   736→
   737→	// Subscribe to newly data columns stored in the database.
   738→	subscription, identsChan := s.dataColumnStorage.Subscribe()
   739→	defer subscription.Unsubscribe()
   740→
   741→	// Get the count of data columns we already have in the store.
   742→	summary := s.dataColumnStorage.Summary(root)
   743→	storedDataColumnsCount := summary.Count()
   744→
   745→	minimumColumnCountToReconstruct := peerdas.MinimumColumnCountToReconstruct()
   746→
   747→	// As soon as we have enough data column sidecars, we can reconstruct the missing ones.
   748→	// We don't need to wait for the rest of the data columns to declare the block as available.
   749→	if storedDataColumnsCount >= minimumColumnCountToReconstruct {
   750→		return nil
   751→	}
   752→
   753→	// Get a map of data column indices that are not currently available.
   754→	missingMap, err := missingDataColumnIndices(s.dataColumnStorage, root, peerInfo.CustodyColumns)
   755→	if err != nil {
   756→		return errors.Wrap(err, "missing data columns")
   757→	}
   758→
   759→	// If there are no missing indices, all data column sidecars are available.
   760→	// This is the happy path.
   761→	if len(missingMap) == 0 {
   762→		return nil
   763→	}
   764→
   765→	if s.startWaitingDataColumnSidecars != nil {
   766→		s.startWaitingDataColumnSidecars <- true
   767→	}
   768→
   769→	// Log for DA checks that cross over into the next slot; helpful for debugging.
   770→	nextSlot, err := slots.StartTime(s.genesisTime, block.Slot()+1)
   771→	if err != nil {
   772→		return fmt.Errorf("unable to determine slot start time: %w", err)
   773→	}
   774→
   775→	// Avoid logging if DA check is called after next slot start.
   776→	if nextSlot.After(time.Now()) {
   777→		timer := time.AfterFunc(time.Until(nextSlot), func() {
   778→			missingMapCount := uint64(len(missingMap))
   779→
   780→			if missingMapCount == 0 {
   781→				return
   782→			}
   783→
   784→			var (
   785→				expected interface{} = "all"
   786→				missing  interface{} = "all"
   787→			)
   788→
   789→			numberOfColumns := params.BeaconConfig().NumberOfColumns
   790→			colMapCount := uint64(len(peerInfo.CustodyColumns))
   791→
   792→			if colMapCount < numberOfColumns {
   793→				expected = uint64MapToSortedSlice(peerInfo.CustodyColumns)
   794→			}
   795→
   796→			if missingMapCount < numberOfColumns {
   797→				missing = uint64MapToSortedSlice(missingMap)
   798→			}
   799→
   800→			log.WithFields(logrus.Fields{
   801→				"slot":            block.Slot(),
   802→				"root":            fmt.Sprintf("%#x", root),
   803→				"columnsExpected": expected,
   804→				"columnsWaiting":  missing,
   805→			}).Warning("Data columns still missing at slot end")
   806→		})
   807→		defer timer.Stop()
   808→	}
   809→
   810→	for {
   811→		select {
   812→		case idents := <-identsChan:
   813→			if idents.Root != root {
   814→				// This is not the root we are looking for.
   815→				continue
   816→			}
   817→
   818→			for _, index := range idents.Indices {
   819→				// This is a data column we are expecting.
   820→				if _, ok := missingMap[index]; ok {
   821→					storedDataColumnsCount++
   822→				}
   823→
   824→				// As soon as we have more than half of the data columns, we can reconstruct the missing ones.
   825→				// We don't need to wait for the rest of the data columns to declare the block as available.
   826→				if storedDataColumnsCount >= minimumColumnCountToReconstruct {
   827→					return nil
   828→				}
   829→
   830→				// Remove the index from the missing map.
   831→				delete(missingMap, index)
   832→
   833→				// Return if there is no more missing data columns.
   834→				if len(missingMap) == 0 {
   835→					return nil
   836→				}
   837→			}
   838→
   839→		case <-ctx.Done():
   840→			var missingIndices interface{} = "all"
   841→			numberOfColumns := params.BeaconConfig().NumberOfColumns
   842→			missingIndicesCount := uint64(len(missingMap))
   843→
   844→			if missingIndicesCount < numberOfColumns {
   845→				missingIndices = uint64MapToSortedSlice(missingMap)
   846→			}
   847→
   848→			return errors.Wrapf(ctx.Err(), "data column sidecars slot: %d, BlockRoot: %#x, missing: %v", block.Slot(), root, missingIndices)
   849→		}
   850→	}
   851→}
   852→
   853→// areBlobsAvailable blocks until all BlobSidecars committed to in the block are available,
   854→// or an error or context cancellation occurs. A nil result means that the data availability check is successful.
   855→func (s *Service) areBlobsAvailable(ctx context.Context, root [fieldparams.RootLength]byte, block interfaces.ReadOnlyBeaconBlock) error {
   856→	blockSlot := block.Slot()
   857→
   858→	// We are only required to check within MIN_EPOCHS_FOR_BLOB_SIDECARS_REQUESTS
   859→	if !params.WithinDAPeriod(slots.ToEpoch(block.Slot()), slots.ToEpoch(s.CurrentSlot())) {
   860→		return nil
   861→	}
   862→
   863→	body := block.Body()
   864→	if body == nil {
   865→		return errors.New("invalid nil beacon block body")
   866→	}
   867→	kzgCommitments, err := body.BlobKzgCommitments()
   868→	if err != nil {
   869→		return errors.Wrap(err, "could not get KZG commitments")
   870→	}
   871→	// expected is the number of kzg commitments observed in the block.
   872→	expected := len(kzgCommitments)
   873→	if expected == 0 {
   874→		return nil
   875→	}
   876→	// get a map of BlobSidecar indices that are not currently available.
   877→	missing, err := missingBlobIndices(s.blobStorage, root, kzgCommitments, block.Slot())
   878→	if err != nil {
   879→		return errors.Wrap(err, "missing indices")
   880→	}
   881→	// If there are no missing indices, all BlobSidecars are available.
   882→	if len(missing) == 0 {
   883→		return nil
   884→	}
   885→
   886→	// The gossip handler for blobs writes the index of each verified blob referencing the given
   887→	// root to the channel returned by blobNotifiers.forRoot.
   888→	nc := s.blobNotifiers.forRoot(root, block.Slot())
   889→
   890→	// Log for DA checks that cross over into the next slot; helpful for debugging.
   891→	nextSlot, err := slots.StartTime(s.genesisTime, block.Slot()+1)
   892→	if err != nil {
   893→		return fmt.Errorf("unable to determine slot start time: %w", err)
   894→	}
   895→	// Avoid logging if DA check is called after next slot start.
   896→	if nextSlot.After(time.Now()) {
   897→		nst := time.AfterFunc(time.Until(nextSlot), func() {
   898→			if len(missing) == 0 {
   899→				return
   900→			}
   901→
   902→			log.WithFields(logrus.Fields{
   903→				"slot":          blockSlot,
   904→				"root":          fmt.Sprintf("%#x", root),
   905→				"blobsExpected": expected,
   906→				"blobsWaiting":  len(missing),
   907→			}).Error("Still waiting for blobs DA check at slot end.")
   908→		})
   909→		defer nst.Stop()
   910→	}
   911→	for {
   912→		select {
   913→		case idx := <-nc:
   914→			// Delete each index seen in the notification channel.
   915→			delete(missing, idx)
   916→			// Read from the channel until there are no more missing sidecars.
   917→			if len(missing) > 0 {
   918→				continue
   919→			}
   920→			// Once all sidecars have been observed, clean up the notification channel.
   921→			s.blobNotifiers.delete(root)
   922→			return nil
   923→		case <-ctx.Done():
   924→			return errors.Wrapf(ctx.Err(), "context deadline waiting for blob sidecars slot: %d, BlockRoot: %#x", block.Slot(), root)
   925→		}
   926→	}
   927→}
   928→
   929→// uint64MapToSortedSlice produces a sorted uint64 slice from a map.
   930→func uint64MapToSortedSlice(input map[uint64]bool) []uint64 {
   931→	output := make([]uint64, 0, len(input))
   932→	for idx := range input {
   933→		output = append(output, idx)
   934→	}
   935→	slices.Sort[[]uint64](output)
   936→	return output
   937→}
   938→
   939→// lateBlockTasks  is called 4 seconds into the slot and performs tasks
   940→// related to late blocks. It emits a MissedSlot state feed event.
   941→// It calls FCU and sets the right attributes if we are proposing next slot
   942→// it also updates the next slot cache and the proposer index cache to deal with skipped slots.
   943→func (s *Service) lateBlockTasks(ctx context.Context) {
   944→	currentSlot := s.CurrentSlot()
   945→	if currentSlot == s.HeadSlot() {
   946→		return
   947→	}
   948→	s.cfg.ForkChoiceStore.RLock()
   949→	defer s.cfg.ForkChoiceStore.RUnlock()
   950→	// return early if we are in init sync
   951→	if !s.inRegularSync() {
   952→		return
   953→	}
   954→	s.headLock.RLock()
   955→	headRoot := s.headRoot()
   956→	headState := s.headState(ctx)
   957→	s.headLock.RUnlock()
   958→	lastRoot, lastState := transition.LastCachedState()
   959→	if lastState == nil {
   960→		lastRoot, lastState = headRoot[:], headState
   961→	}
   962→	// Copy all the field tries in our cached state in the event of late
   963→	// blocks.
   964→	lastState.CopyAllTries()
   965→	if err := transition.UpdateNextSlotCache(ctx, lastRoot, lastState); err != nil {
   966→		log.WithError(err).Debug("Could not update next slot state cache")
   967→	}
   968→	if err := s.handleEpochBoundary(ctx, currentSlot, headState, headRoot[:]); err != nil {
   969→		log.WithError(err).Error("Could not update epoch boundary caches")
   970→	}
   971→	// return early if we already started building a block for the current
   972→	// head root
   973→	_, has := s.cfg.PayloadIDCache.PayloadID(s.CurrentSlot()+1, headRoot)
   974→	if has {
   975→		return
   976→	}
   977→
   978→	attribute := s.getPayloadAttribute(ctx, headState, s.CurrentSlot()+1, headRoot[:])
   979→	// return early if we are not proposing next slot
   980→	if attribute.IsEmpty() {
   981→		headBlock, err := s.headBlock()
   982→		if err != nil {
   983→			log.WithError(err).WithField("head_root", headRoot).Error("Unable to retrieve head block to fire payload attributes event")
   984→		}
   985→		// notifyForkchoiceUpdate fires the payload attribute event. But in this case, we won't
   986→		// call notifyForkchoiceUpdate, so the event is fired here.
   987→		go s.firePayloadAttributesEvent(s.cfg.StateNotifier.StateFeed(), headBlock, headRoot, s.CurrentSlot()+1)
   988→		return
   989→	}
   990→
   991→	s.headLock.RLock()
   992→	headBlock, err := s.headBlock()
   993→	if err != nil {
   994→		s.headLock.RUnlock()
   995→		log.WithError(err).Debug("could not perform late block tasks: failed to retrieve head block")
   996→		return
   997→	}
   998→	s.headLock.RUnlock()
   999→
  1000→	fcuArgs := &fcuConfig{
  1001→		headState:  headState,
  1002→		headRoot:   headRoot,
  1003→		headBlock:  headBlock,
  1004→		attributes: attribute,
  1005→	}
  1006→	_, err = s.notifyForkchoiceUpdate(ctx, fcuArgs)
  1007→	if err != nil {
  1008→		log.WithError(err).Debug("could not perform late block tasks: failed to update forkchoice with engine")
  1009→	}
  1010→}
  1011→
  1012→// waitForSync blocks until the node is synced to the head.
  1013→func (s *Service) waitForSync() error {
  1014→	select {
  1015→	case <-s.syncComplete:
  1016→		return nil
  1017→	case <-s.ctx.Done():
  1018→		return errors.New("context closed, exiting goroutine")
  1019→	}
  1020→}
  1021→
  1022→func (s *Service) handleInvalidExecutionError(ctx context.Context, err error, blockRoot, parentRoot [fieldparams.RootLength]byte) error {
  1023→	if IsInvalidBlock(err) && InvalidBlockLVH(err) != [32]byte{} {
  1024→		return s.pruneInvalidBlock(ctx, blockRoot, parentRoot, InvalidBlockLVH(err))
  1025→	}
  1026→	return err
  1027→}
  1028→
  1029→// In the event of an issue processing a block we rollback changes done to the db and our caches
  1030→// to always ensure that the node's internal state is consistent.
  1031→func (s *Service) rollbackBlock(ctx context.Context, blockRoot [32]byte) {
  1032→	log.Warnf("Rolling back insertion of block with root %#x due to processing error", blockRoot)
  1033→	if err := s.cfg.StateGen.DeleteStateFromCaches(ctx, blockRoot); err != nil {
  1034→		log.WithError(err).Errorf("Could not delete state from caches with block root %#x", blockRoot)
  1035→	}
  1036→	if err := s.cfg.BeaconDB.DeleteBlock(ctx, blockRoot); err != nil {
  1037→		log.WithError(err).Errorf("Could not delete block with block root %#x", blockRoot)
  1038→	}
  1039→}
  1040→

